architecture synthesis of qmtech_k325t_cm4 is

   component mig_ddr3 is
      port (
         ddr3_dq             : inout std_logic_vector(15 downto 0);
         ddr3_dqs_p          : inout std_logic_vector(1 downto 0);
         ddr3_dqs_n          : inout std_logic_vector(1 downto 0);
         ddr3_addr           : out   std_logic_vector(13 downto 0);
         ddr3_ba             : out   std_logic_vector(2 downto 0);
         ddr3_ras_n          : out   std_logic;
         ddr3_cas_n          : out   std_logic;
         ddr3_we_n           : out   std_logic;
         ddr3_reset_n        : out   std_logic;
         ddr3_ck_p           : out   std_logic_vector(0 downto 0);
         ddr3_ck_n           : out   std_logic_vector(0 downto 0);
         ddr3_cke            : out   std_logic_vector(0 downto 0);
         ddr3_dm             : out   std_logic_vector(1 downto 0);
         ddr3_odt            : out   std_logic_vector(0 downto 0);
         app_addr            : in    std_logic_vector(27 downto 0);
         app_cmd             : in    std_logic_vector(2 downto 0);
         app_en              : in    std_logic;
         app_wdf_data        : in    std_logic_vector(127 downto 0);
         app_wdf_end         : in    std_logic;
         app_wdf_mask        : in    std_logic_vector(15 downto 0);
         app_wdf_wren        : in    std_logic;
         app_rd_data         : out   std_logic_vector(127 downto 0);
         app_rd_data_end     : out   std_logic;
         app_rd_data_valid   : out   std_logic;
         app_rdy             : out   std_logic;
         app_wdf_rdy         : out   std_logic;
         app_sr_req          : in    std_logic;
         app_ref_req         : in    std_logic;
         app_zq_req          : in    std_logic;
         app_sr_active       : out   std_logic;
         app_ref_ack         : out   std_logic;
         app_zq_ack          : out   std_logic;
         ui_clk              : out   std_logic;
         ui_clk_sync_rst     : out   std_logic;
         init_calib_complete : out   std_logic;
         sys_clk_i           : in    std_logic;
         device_temp_i       : in    std_logic_vector(11 downto 0);
         sys_rst             : in    std_logic
      );
   end component;

   -- board clocks
   signal clk_fb, clk_fb_b             : std_logic;
   signal clk100_u, clk200_u, clk162_u : std_logic;
   signal clk100, clk200, clk162       : std_logic;
   signal mmcm_locked                  : std_logic;

   -- DDR3
   signal por_cnt           : unsigned(15 downto 0) := (others => '0');
   signal mig_sys_rst_n     : std_logic := '0';
   signal mig_ui_clk        : std_logic;
   signal mig_ui_rst        : std_logic;
   signal mig_calib         : std_logic;
   signal mem_not_ready     : std_logic;
   signal app_addr          : std_logic_vector(27 downto 0);
   signal app_cmd           : std_logic_vector(2 downto 0);
   signal app_en, app_rdy   : std_logic;
   signal app_wdf_data      : std_logic_vector(127 downto 0);
   signal app_wdf_end       : std_logic;
   signal app_wdf_mask      : std_logic_vector(15 downto 0);
   signal app_wdf_wren      : std_logic;
   signal app_wdf_rdy       : std_logic;
   signal app_rd_data       : std_logic_vector(127 downto 0);
   signal app_rd_data_valid : std_logic;
   signal mem_write, mem_read          : std_logic;
   signal mem_address                  : std_logic_vector(31 downto 0);
   signal mem_writedata, mem_readdata  : std_logic_vector(15 downto 0);
   signal mem_byteenable               : std_logic_vector(1 downto 0);
   signal mem_burstcount               : std_logic_vector(7 downto 0);
   signal mem_readdatavalid            : std_logic;
   signal mem_waitrequest              : std_logic;

   -- Rockchip bridge, SD emulator, keyboard emulator
   signal sd_cs_n_s, sd_sclk_s, sd_mosi_s, sd_miso_s : std_logic;
   signal sd_rd_req, sd_wr_req, sd_rd_ready, sd_rd_error, sd_wr_ack, sd_inited : std_logic;
   signal sd_lba            : unsigned(31 downto 0);
   signal sd_seq, sd_cmd_cnt, sd_last_cmd : unsigned(7 downto 0);
   signal rbuf_addr, wbuf_addr : unsigned(8 downto 0);
   signal rbuf_data, wbuf_data : std_logic_vector(7 downto 0);
   signal wbuf_we           : std_logic;
   signal qnice_uart_rx     : std_logic;
   signal qnice_uart_tx     : std_logic;
   signal kio8, kio10       : std_logic;
   signal kb_col_idx        : integer range 0 to 15;
   signal kb_col            : std_logic_vector(7 downto 0);
   signal rk_joya, rk_joyb  : std_logic_vector(4 downto 0);
   signal rk_ctrl           : std_logic_vector(7 downto 0);
   signal rk_pots           : std_logic_vector(31 downto 0);   -- pot1 x/y, pot2 x/y (SID values)
   -- configuration flash (Rockchip pass-through) and warm boot into another slot
   signal fl_sck, fl_cs_n, fl_mosi, fl_miso : std_logic;
   signal ip_toggle         : std_logic;
   signal ip_addr           : std_logic_vector(31 downto 0);
   signal core_pots         : std_logic_vector(31 downto 0);   -- the core inverts its pot inputs
   signal joya_n, joyb_n    : std_logic_vector(4 downto 0);
   signal caps_n, rest_n    : std_logic;

   -- reset
   signal reset_s           : std_logic_vector(2 downto 0) := (others => '0');
   signal sys_reset_n       : std_logic := '0';
   signal heartbeat         : unsigned(25 downto 0) := (others => '0');

   ---------------------------------------------------------------------------------------
   -- from top_mega65-r6.vhd
   ---------------------------------------------------------------------------------------
--@R6_DECLARATIONS@

begin

   ---------------------------------------------------------------------------------------
   -- Clocks: 50 MHz -> VCO 1200 MHz -> 162.71 / 100 / 200 MHz
   ---------------------------------------------------------------------------------------
   i_mmcm : MMCME2_BASE
      generic map (
         BANDWIDTH        => "OPTIMIZED",
         CLKIN1_PERIOD    => 20.0,
         DIVCLK_DIVIDE    => 1,
         CLKFBOUT_MULT_F  => 24.0,         -- 1200 MHz
         CLKOUT0_DIVIDE_F => 7.375,        -- 162.71 MHz  Rockchip bridge
         CLKOUT1_DIVIDE   => 12,           -- 100 MHz     M2M clk_i
         CLKOUT2_DIVIDE   => 6             -- 200 MHz     MIG system clock
      )
      port map (
         CLKIN1   => clk_in,
         CLKFBIN  => clk_fb_b,
         CLKFBOUT => clk_fb,
         CLKOUT0  => clk162_u,
         CLKOUT1  => clk100_u,
         CLKOUT2  => clk200_u,
         LOCKED   => mmcm_locked,
         PWRDWN   => '0',
         RST      => '0'
      );
   i_bufg_fb  : BUFG port map (I => clk_fb,   O => clk_fb_b);
   i_bufg_162 : BUFG port map (I => clk162_u, O => clk162);
   i_bufg_100 : BUFG port map (I => clk100_u, O => clk100);
   i_bufg_200 : BUFG port map (I => clk200_u, O => clk200);

   ---------------------------------------------------------------------------------------
   -- Reset: SW3 or the Rockchip (ctrl bit 0) holds the whole M2M system in reset
   ---------------------------------------------------------------------------------------
   process (clk100)
   begin
      if rising_edge(clk100) then
         reset_s     <= reset_s(1 downto 0) & (reset_button and mmcm_locked);
         sys_reset_n <= reset_s(2) and not rk_ctrl(0);
         heartbeat   <= heartbeat + 1;
      end if;
   end process;

   ---------------------------------------------------------------------------------------
   -- DDR3: MIG + Avalon bridge (both in ui_clk)
   ---------------------------------------------------------------------------------------
   process (clk_in)
   begin
      if rising_edge(clk_in) then
         if mmcm_locked = '0' then
            por_cnt       <= (others => '0');
            mig_sys_rst_n <= '0';
         elsif por_cnt /= x"FFFF" then
            por_cnt       <= por_cnt + 1;
            mig_sys_rst_n <= '0';
         else
            mig_sys_rst_n <= '1';
         end if;
      end if;
   end process;

   i_mig : mig_ddr3
      port map (
         ddr3_dq => ddr3_dq, ddr3_dqs_p => ddr3_dqs_p, ddr3_dqs_n => ddr3_dqs_n,
         ddr3_addr => ddr3_addr, ddr3_ba => ddr3_ba, ddr3_ras_n => ddr3_ras_n,
         ddr3_cas_n => ddr3_cas_n, ddr3_we_n => ddr3_we_n, ddr3_reset_n => ddr3_reset_n,
         ddr3_ck_p => ddr3_ck_p, ddr3_ck_n => ddr3_ck_n, ddr3_cke => ddr3_cke,
         ddr3_dm => ddr3_dm, ddr3_odt => ddr3_odt,
         app_addr => app_addr, app_cmd => app_cmd, app_en => app_en,
         app_wdf_data => app_wdf_data, app_wdf_end => app_wdf_end, app_wdf_mask => app_wdf_mask,
         app_wdf_wren => app_wdf_wren, app_rd_data => app_rd_data, app_rd_data_end => open,
         app_rd_data_valid => app_rd_data_valid, app_rdy => app_rdy, app_wdf_rdy => app_wdf_rdy,
         app_sr_req => '0', app_ref_req => '0', app_zq_req => '0',
         app_sr_active => open, app_ref_ack => open, app_zq_ack => open,
         ui_clk => mig_ui_clk, ui_clk_sync_rst => mig_ui_rst, init_calib_complete => mig_calib,
         sys_clk_i => clk200,
         device_temp_i => x"9F1",          -- ~40 C constant (no XADC reader in this design)
         sys_rst => mig_sys_rst_n
      );

   mem_not_ready <= mig_ui_rst or not mig_calib;

   i_avm_mig : entity work.avm_mig
      generic map (ADDR_BITS => 27)
      port map (
         clk => mig_ui_clk, rst => mem_not_ready,
         avm_write => mem_write, avm_read => mem_read, avm_address => mem_address,
         avm_writedata => mem_writedata, avm_byteenable => mem_byteenable,
         avm_burstcount => mem_burstcount, avm_readdata => mem_readdata,
         avm_readdatavalid => mem_readdatavalid, avm_waitrequest => mem_waitrequest,
         app_addr => app_addr, app_cmd => app_cmd, app_en => app_en, app_rdy => app_rdy,
         app_wdf_data => app_wdf_data, app_wdf_end => app_wdf_end, app_wdf_wren => app_wdf_wren,
         app_wdf_mask => app_wdf_mask, app_wdf_rdy => app_wdf_rdy, app_rd_data => app_rd_data,
         app_rd_data_valid => app_rd_data_valid
      );

   ---------------------------------------------------------------------------------------
   -- Rockchip bridge: SD sectors, key matrix, joysticks, QNICE UART
   ---------------------------------------------------------------------------------------
   i_rk_bridge : entity work.rk_bridge
      generic map (BIT_CLKS => 1412,       -- 162.71 MHz / 115200 baud (QNICE UART)
                   CORE_ID  => x"02")      -- C64
      port map (
         clk => clk162, cpuclk => clk100,
         spi_sck => rk_sck, spi_cs_n => rk_cs_n, spi_mosi => rk_mosi, spi_miso => rk_miso,
         sd_rd_req => sd_rd_req, sd_wr_req => sd_wr_req, sd_lba => sd_lba, sd_seq => sd_seq,
         sd_inited => sd_inited, sd_cmd_cnt => sd_cmd_cnt, sd_last_cmd => sd_last_cmd,
         sd_rd_ready => sd_rd_ready, sd_rd_error => sd_rd_error, sd_wr_ack => sd_wr_ack,
         rbuf_addr => rbuf_addr, rbuf_data => rbuf_data,
         wbuf_we => wbuf_we, wbuf_addr => wbuf_addr, wbuf_data => wbuf_data,
         mon_rx => qnice_uart_rx, mon_tx => qnice_uart_tx,
         matrix_col_idx => kb_col_idx, matrix_col => kb_col,
         joya => rk_joya, joyb => rk_joyb, ctrl => rk_ctrl,
         pots => rk_pots,
         flash_active => open, flash_sck => fl_sck, flash_cs_n => fl_cs_n,
         flash_mosi => fl_mosi, flash_miso => fl_miso,
         iprog_toggle => ip_toggle, iprog_addr => ip_addr,
         spi_active => open
      );

   i_sd_emu : entity work.sd_emu
      generic map (SYNC_IN => true)        -- SimpleSDHC runs on its own 25 MHz clock
      port map (
         clk => clk100, sd_cs_n => sd_cs_n_s, sd_sclk => sd_sclk_s, sd_mosi => sd_mosi_s,
         sd_miso => sd_miso_s,
         rd_req => sd_rd_req, wr_req => sd_wr_req, req_lba => sd_lba, req_seq => sd_seq,
         rd_ready => sd_rd_ready, rd_error => sd_rd_error, wr_ack => sd_wr_ack,
         rbuf_addr => rbuf_addr, rbuf_data => rbuf_data,
         wbuf_we => wbuf_we, wbuf_addr => wbuf_addr, wbuf_data => wbuf_data,
         inited => sd_inited, cmd_count => sd_cmd_cnt, last_cmd => sd_last_cmd
      );

   caps_n <= not rk_ctrl(2);
   rest_n <= not rk_ctrl(1);

   i_kbd_emu : entity work.m65kbd_emu
      generic map (SYNC_CYCLES => 500)     -- 5 us at 100 MHz
      port map (
         clk => clk100, kio8 => kio8, kio10 => kio10,
         matrix_col_idx => kb_col_idx, matrix_col => kb_col,
         capslock_n => caps_n, restore_n => rest_n
      );

   ---------------------------------------------------------------------------------------
   -- Configuration flash: x1 SPI through the Rockchip bridge (DQ0 = MOSI, DQ1 = MISO,
   -- DQ2 / DQ3 = WP# / HOLD# held high).  CCLK is the user clock of STARTUPE2.
   ---------------------------------------------------------------------------------------
   i_startup : STARTUPE2
      generic map (PROG_USR => "FALSE", SIM_CCLK_FREQ => 0.0)
      port map (CFGCLK => open, CFGMCLK => open, EOS => open, PREQ => open,
                CLK => '0', GSR => '0', GTS => '0', KEYCLEARB => '1', PACK => '0',
                USRCCLKO => fl_sck, USRCCLKTS => '0', USRDONEO => '1', USRDONETS => '1');
   qspi_csn   <= fl_cs_n;
   qspi_db(0) <= fl_mosi;
   qspi_db(1) <= 'Z';
   qspi_db(2) <= '1';
   qspi_db(3) <= '1';
   fl_miso    <= qspi_db(1);

   -- Rockchip command 0x60: warm boot into the bitstream at ip_addr (flash slot)
   i_iprog : entity work.rk_iprog
      port map (clk => clk100, iprog_toggle => ip_toggle, iprog_addr => ip_addr);

   core_pots <= not rk_pots;               -- SID POTX/POTY = not pot input (fpga64_sid_iec)
   joya_n <= not rk_joya;                  -- b0 up b1 down b2 left b3 right b4 fire
   joyb_n <= not rk_joyb;

   ---------------------------------------------------------------------------------------
   -- Unused MEGA65 ports of the core: idle levels
   ---------------------------------------------------------------------------------------
   cart_reset_in <= '1'; cart_game_in <= '1'; cart_exrom_in <= '1';
   cart_nmi_in   <= '1'; cart_irq_in  <= '1'; cart_roml_in  <= '1'; cart_romh_in <= '1';
   cart_ba_in    <= '1'; cart_rw_in   <= '1'; cart_io1_in   <= '1'; cart_io2_in  <= '1';
   cart_d_in     <= (others => '1');
   cart_a_in     <= (others => '1');

   led(0) <= mig_calib;
   led(1) <= main_drive_led;
   led(2) <= heartbeat(25);

   ---------------------------------------------------------------------------------------
   -- MiSTer2MEGA65 framework and the C64 core (from top_mega65-r6.vhd, pins remapped)
   ---------------------------------------------------------------------------------------
--@FRAMEWORK@

--@CORE@

end architecture synthesis;
